Translate("ptBR", "grol-the-destroyer", {
	title = "Grol, o Destruidor",
	subtitle = "Senhor dos Malhorrendo",
	found = "Domínio de Malhorrendo, no noroeste da Barreira do Inferno",
	hint = "Procure o senhor dos ogros em seu domínio do norte.",
	allegiance = "Malhorrendo · Razelikh, o Profanador",
	aliases = { "Grol" },
	sections = {
		{
			title = "Resumo",
			text = [=[Grol, o Destruidor, governa os ogros Malhorrendo a partir do {link:dreadmaul-hold}Domínio de Malhorrendo{/link}. Foi um dia um chefe {link:ogres}ogro{/link}. Tomou um terço do amuleto de {link:razelikh-the-defiler}Razelikh{/link} em troca de poder e vida sem fim, e o presente do demônio o refez em algo mais próximo de um demônio. Nenhuma arma comum pode matá-lo enquanto ele estiver na {link:blasted-lands}Barreira do Inferno{/link}. Três soldados do regimento perdido da {link:horde}Horda{/link} lhe foram dados como escravos.]=],
		},
	},
	chapters = {
		{
			title = "O Amuleto de Grol",
			hint = [=[Derrube o senhor dos Malhorrendo com uma lâmina que traz o nome do Profanador.]=],
			text = [=[Grol foi o primeiro da tríade a aprender que a imortalidade tem um preço. A arma forjada no próprio nome do Profanador quebrou sua proteção, e sua parte do amuleto foi tomada de seu corpo.]=],
		},
	},
})

Translate("ptBR", "archmage-allistarj", {
	title = "Arquimago Allistarj",
	subtitle = "Arquimago dos Shadowsworn",
	found = "Dentro das Cavernas Serpeantes",
	hint = [=[Procure o arquimago que governa os cultistas das cavernas do leste.]=],
	allegiance = "Shadowsworn · Razelikh, o Profanador",
	aliases = { "Allistarj" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Arquimago Allistarj lidera os cultistas Shadowsworn das {link:serpent-s-coil}Cavernas Serpeantes{/link}. É um dos três que tomaram uma parte do amuleto de {link:razelikh-the-defiler}Razelikh{/link}, e está preso ao Profanador por ela. Foi o torturador do regimento perdido da {link:horde}Horda{/link}. Em suas cavernas, Trebor e seu tenente {link:kirith-the-damned}Kirith{/link} foram atormentados alternadamente, cada um forçado a ver o outro, e foram os experimentos de Allistarj que quebraram a alma de Kirith. Três dos soldados do regimento ainda o servem.]=],
