			title = "O Amuleto de Allistarj",
			hint = [=[Enfrente o arquimago nas Cavernas Serpeantes com a ruína do Profanador.]=],
			text = [=[O arquimago vendera a alma pelo poder de atormentar os outros. Quando ele caiu, seu terço do amuleto lhe foi tomado.]=],
		},
	},
})

Translate("ptBR", "lady-sevine", {
	title = "Lady Sevine",
	subtitle = "Bruxa dos Shadowsworn",
