		},
	},
})

Translate("ptBR", "kirith-the-damned", {
	title = "Kirith, o Maldito",
	subtitle = "O Tenente Quebrado",
	found = "A caverna mais funda das Cavernas Serpeantes",
	hint = [=[Descubra o que aconteceu ao tenente que nunca saiu das cavernas.]=],
	allegiance = "Horda (outrora)",
	aliases = { "Kirith", "Tenente Kirith" },
	sections = {
		{
			title = "Resumo",
			text = [=[Kirith era o tenente de Trebor, o comandante de um regimento da {link:horde}Horda{/link} perdido na {link:blasted-lands}Barreira do Inferno{/link}. Ele e seu comandante foram torturados lado a lado pelo {link:archmage-allistarj}Arquimago Allistarj{/link}. Numa trégua de seu tormento, foi Kirith quem descobriu como os soldados presos do regimento poderiam ser libertados. Sua própria vontade cedeu por fim. Os experimentos retorceram sua alma numa fera vil que assombra o fundo das {link:serpent-s-coil}Cavernas Serpeantes{/link}.]=],
		},
	},
	chapters = {
		{
			title = "O Espírito de Kirith",
			hint = "Liberte o tenente da fera em que ele se tornou.",
			text = [=[Quando a fera foi morta, o espírito de Kirith ergueu-se dela. Tinha pouco tempo e não o desperdiçou. Falou da tríade e do amuleto que os três capitães compartilhavam, a única chave capaz de invocar {link:razelikh-the-defiler}o Profanador{/link}. Depois mandou seus salvadores de volta a seu comandante.]=],
		},
	},
})

