Translate("ptBR", "quartermaster-lungertz", {
	title = "Intendente Lungertz",
	subtitle = "Intendente de Etergarde",
	found = "Bastilha de Etergarde",
	hint = [=[Fale com o homem que conta cada caixote que chega a Etergarde.]=],
	allegiance = "Bastilha de Etergarde · Kirin Tor",
	aliases = { "Lungertz" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Intendente Lungertz cuida dos estoques da {link:nethergarde-keep}Bastilha de Etergarde{/link}. É a linha de vida da bastilha com os reinos. Comida, armas, pedras de poder e os reagentes de que seus magos precisam, tudo tem de vir pela longa estrada de {link:stormwind-city}Ventobravo{/link}, e ele responde por tudo isso. Coisas demais nunca chegam. {link:ogres}Ogros{/link} atacam as caravanas no pântano, e carroças se perdem entre {link:darkshire}Vila Sombria{/link} e a bastilha. Ele recebe cada entrega como se fosse um pequeno milagre, e às vezes é.]=],
		},
	},
	chapters = {
		{
			title = "A Estrada para Etergarde",
			hint = "Leve suprimentos pela longa estrada até a bastilha.",
			text = [=[Pedras de poder de {link:darkshire}Vila Sombria{/link} que perderiam a carga se esperassem pela próxima caravana. Um barril marcado com o nome dele, encontrado longe da estrada. Um último caixote salvo da caravana arruinada do {link:watcher-biggs}Vigia Biggs{/link}, que a bastilha já dera como perdida junto com o condutor. Cada um chegou a ele pela mão de um viajante, e cada um contava a mesma história. {link:nethergarde-keep}Etergarde{/link} tem falta de tudo, sobretudo dos cristais de Azoran sem os quais seus magos não podem passar.]=],
		},
	},
	mentions = {
		{ text = "Suprimentos para {link:nethergarde-keep}Etergarde{/link}" },
		{ text = "Os Suprimentos Perdidos" },
		{ text = "Entregue o Carregamento" },
	},
})

Translate("ptBR", "watcher-mahar-ba", {
	title = "Vigia Mahar Ba",
	subtitle = "Estudioso de Etergarde",
