		},
	},
	mentions = {
		{ text = "A Incumbência de Mazen" },
	},
})

Translate("ptBR", "thadius-grimshade", {
	title = "Thadius Grimshade",
	subtitle = "Adivinho de Etergarde",
	found = "A torre dos magos da Bastilha de Etergarde",
