	allegiance = "Clã Martelo Feroz",
	aliases = { "Grimshade" },
	sections = {
		{
			title = "Resumo",
			text = [=[Thadius Grimshade é um {link:dwarves}anão{/link} Martelo Feroz e um adivinho. Deixou o {link:aerie-peak}Ninho da Águia{/link} há anos em busca de um saber mais sombrio, e encontrou lugar para ele na torre dos magos de {link:nethergarde-keep}Etergarde{/link}. Seu antigo clã não o esqueceu, e ele não os esqueceu. Ainda usa suas artes pelos Martelo Feroz, embora nunca de graça.]=],
