	},
	chapters = {
		{
			title = "A Adivinhação",
			hint = "Traga ao adivinho uma pena de grifo, e pague o seu preço.",
			text = [=[Os mestres de grifos do {link:aerie-peak}Ninho da Águia{/link} lhe enviaram uma pena do ninho de Sharpbeak, um jovem grifo que fora roubado. Grimshade pediu primeiro um preço: o medalhão do troll Nekrum Gutchewer, de {red:zul-farrak}Zul'Farrak{/red}, que concedera a seu dono uma vida anormalmente longa. Ele esperava aprender o segredo do medalhão sem a sua maldição. Quando o medalhão foi seu, realizou a adivinhação, seguiu o fio da pena até o grifo e encontrou Sharpbeak preso numa cidade troll das {link:the-hinterlands}Terras Agrestes{/link}.]=],
		},
	},
	mentions = {
		{ text = "O Medalhão de Nekrum" },
		{ text = "De Volta às {link:the-hinterlands}Terras Agrestes{/link}" },
	},
})

Translate("ptBR", "ambassador-ardalan", {
