		},
	},
})

Translate("ptBR", "kum-isha-the-collector", {
	title = "Kum'isha, o Colecionador",
	subtitle = "Buscador de Draenethyst",
	found = "Nos ermos perto do Cerro do Profanador",
	hint = "Procure o exilado que recolhe cristais no coração dos ermos.",
	allegiance = "Os draenei perdidos",
	aliases = { "Kum'isha" },
	sections = {
		{
			title = "Resumo",
			text = [=[Kum'isha, o Colecionador, é um dos draenei perdidos que vagam pela {link:blasted-lands}Barreira do Inferno{/link}, um exilado de um povo antigo vindo de um mundo além do {link:dark-portal}Portal Negro{/link}. Mantém um acampamento no coração dos ermos e recolhe draenethyst, um cristal de sua terra natal que ainda pode ser encontrado na terra vermelha. Acredita que, com o bastante dele, pode abrir uma fenda e levar seu povo para casa.]=],
		},
		{
			title = "Importância",
			text = [=[Kum'isha é amargo, orgulhoso e de língua afiada. {link:humans}Humanos{/link} e orcs se queixam, cada um, do fedor do outro, observa ele, mas para o seu nariz todos os povos deste mundo cheiram igual, e o que ele sente neles é a ganância. A ganância lhe custou o lar, diz ele, e a ganância pagará seu retorno. Troca seus tesouros de bom grado com quem lhe traz cristais, e os despreza por aceitarem a troca.]=],
		},
		{
			title = "Feitos",
			text = [=[• Procura draenethyst pela {link:blasted-lands}Barreira do Inferno{/link}, sobretudo as raras esferas sem falhas.
• Tentou abrir uma fenda para sua terra natal.
• Paga por cada fragmento de cristal que lhe trazem, e despreza quem os traz.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica conta como Kum'isha e seus companheiros vieram para a {link:blasted-lands}Barreira do Inferno{/link}, nem há quanto tempo vagam por lá.]=],
		},
	},
	chapters = {
		{
			title = "A Esfera sem Falhas",
			hint = "Traga ao colecionador o cristal mais raro dos ermos.",
			text = [=[Draenei passaram vidas inteiras em busca de uma única esfera de draenethyst sem falhas, disse Kum'isha, e morreram com a busca inacabada. Quando uma foi posta em suas mãos, ele não pôde acreditar. Tentou de imediato conjurar um portal para casa. A tentativa falhou. Ele não perdeu a esperança. Pediu outra esfera.]=],
		},
		{
			title = "O Lixo de um Draenei",
			hint = "Traga ao colecionador os fragmentos menores do cristal.",
			text = [=[Os fragmentos imperfeitos de draenethyst nunca abrirão um caminho para casa. Mesmo assim, Kum'isha os aceita, pois podem servir a seu povo de outras formas, e paga por eles com os tesouros deste mundo, a que chama de lixo. Diz as mesmas palavras de desprezo a cada vendedor muitas vezes por dia. Admite que detesta este mundo.]=],
		},
	},
	mentions = {
		{ text = "Servir a Kum'isha" },
		{ text = "Os Esforços de Kum'isha" },
		{ text = "Tudo Conta em Grandes Quantidades" },
		{ text = "O Lixo de um Draenei..." },
	},
})

